function view(name){if(name!=='puzzle'&&clock.running)pausePuzzle();['library','studio','puzzle','gallery'].forEach(v=>$(v).hidden=v!==name);['library','puzzle','gallery'].forEach(v=>$(v+'Tab').classList.toggle('active',v===name||(v==='library'&&name==='studio')))}
