function saveLocal(){clearTimeout(saveTimer);if(!art||!ready||!dirty)return saveChain;const target=art,revision=crypto.randomUUID();const snapshot={...target,paint:paintCanvas.toDataURL('image/png'),thumbnail:thumbnail(),updatedAt:Date.now(),revision,pending:true};dirty=false;Object.assign(target,snapshot);saveChain=saveChain.catch(()=>{}).then(async()=>{await putArt(snapshot);await setSetting(`last:${snapshot.family}:${snapshot.profile}`,snapshot.id);if(art===target&&art.revision===revision)$('saveStatus').textContent='Saved on this device';return snapshot}).catch(e=>{if(art===target)dirty=true;$('saveStatus').textContent='Couldn’t save here. Download a copy.';notify('This device couldn’t save the artwork. Please download a picture or editable file.');throw e});return saveChain}
