function renderLibrary(){const level=$('level').value,filtered=PAGES.filter(p=>(theme==='All'||p.theme===theme)&&(level==='All'||p.level===level));$('pageCount').textContent=`${filtered.length} pages to make your own`;$('pageLibrary').replaceChildren();for(const p of filtered){const b=document.createElement('button');b.className='page-card';const img=document.createElement('img');img.src=svgURL(p.svg);img.alt=p.title;img.loading='lazy';const title=document.createElement('strong');title.textContent=p.title;const meta=document.createElement('span');meta.className='details';meta.innerHTML=`<span>${p.theme}</span><span><i class="level-dot"></i>${p.level}</span>`;b.append(img,title,meta);b.onclick=()=>newPage(p);$('pageLibrary').append(b)}if(!filtered.length){const p=document.createElement('p');p.className='empty';p.textContent='Try another detail level for more adventures.';$('pageLibrary').append(p)}}
