const colors=[['#ed7180','Rose'],['#efa76a','Peach'],['#f1ce5d','Sunshine'],['#a3bd73','Leaf'],['#5caa95','Sea green'],['#75b9d2','Sky'],['#8b8cc3','Lavender'],['#bd8cb9','Lilac'],['#d0a181','Sand'],['#785c4b','Brown'],['#38493f','Forest'],['#ffffff','White']];
