function setTool(t){tool=t;['fill','brush','eraser'].forEach(v=>{$(v+'Tool').classList.toggle('selected',v===t);$(v+'Tool').setAttribute('aria-pressed',String(v===t))});$('tip').textContent=t==='fill'?'Tap a color, then tap a shape. Magic!':t==='eraser'?'Erase your colors. The original page stays safe.':'Draw with your finger. Let your imagination wander.'}
