function point(e){const r=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(SIDE-1,Math.floor((e.clientX-r.left)*SIDE/r.width))),y:Math.max(0,Math.min(SIDE-1,Math.floor((e.clientY-r.top)*SIDE/r.height)))}}
function stroke(p){paintCtx.globalCompositeOperation=tool==='eraser'?'destination-out':'source-over';paintCtx.strokeStyle=color;paintCtx.lineWidth=Number($('size').value);paintCtx.lineCap='round';paintCtx.lineJoin='round';paintCtx.beginPath();paintCtx.moveTo(last.x,last.y);paintCtx.lineTo(p.x,p.y);paintCtx.stroke();paintCtx.globalCompositeOperation='source-over';last=p;render();changed()}
