$('clear').onclick=()=>$('resetDialog').showModal();$('cancelReset').onclick=()=>$('resetDialog').close();$('confirmReset').onclick=()=>{$('resetDialog').close();checkpoint();paintCtx.clearRect(0,0,SIDE,SIDE);render();changed()};
