$('upload').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>20000000)throw new Error('Please choose an image smaller than 20 MB.');const url=URL.createObjectURL(file);let image;try{image=await decode(url)}finally{URL.revokeObjectURL(url)}const c=layer();fitImage(c.getContext('2d'),image);const customBase=c.toDataURL('image/jpeg',.88),id=crypto.randomUUID();await openArt({id,key:artKey(family,profile,id),family,profile,pageId:'custom',title:file.name.replace(/\.[^.]+$/,'').slice(0,100)||'My own page',paint:'',customBase,etag:null,updatedAt:Date.now(),revision:crypto.randomUUID(),pending:false});dirty=true;await saveLocal();await flush()}catch(err){notify(err.message==='Please choose an image smaller than 20 MB.'?err.message:'Please choose an image this device can open, such as PNG or JPEG.')}};
$('importArt').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>4500000)throw new Error();const data=JSON.parse(await file.text());if(data.format!=='little-color-club'||data.version!==2||!validateArtwork(data.art)||(!data.art.customBase&&!pageById(data.art.pageId)))throw new Error();const id=crypto.randomUUID();await openArt({...data.art,id,key:artKey(family,profile,id),profile,family,etag:null,revision:crypto.randomUUID(),pending:true});dirty=true;await saveLocal();await flush()}catch{notify('That is not a valid editable Color Club file.')}};
async function gallery(){await saveLocal();view('gallery');const ticket=++galleryTicket;$('galleryItems').textContent='Opening your art shelf…';try{const arts=await mergeGallery(profile);if(ticket!==galleryTicket||$('gallery').hidden)return;$('galleryItems').replaceChildren();if(!arts.length){const empty=document.createElement('div');empty.className='empty';empty.innerHTML='<h2>Your shelf is ready for its first masterpiece.</h2><p>Color a page, then save it here.</p>';const b=document.createElement('button');b.className='primary';b.textContent='Pick a coloring page →';b.onclick=()=>view('library');empty.append(b);$('galleryItems').append(empty)}for(const a of arts){const card=document.createElement('div');card.className='gallery-card';const img=document.createElement('img');img.src=a.thumbnail;img.alt=a.title;const title=document.createElement('strong');title.textContent=a.title;const small=document.createElement('small');small.textContent=a.pending?'Saved here · upload waiting':'Saved for your family';const b=document.createElement('button');b.textContent='Keep coloring';const puzzle=document.createElement('button');puzzle.textContent='Make a puzzle';const open=async play=>{b.disabled=puzzle.disabled=true;try{const record=a.remote?await loadRemote(profile,a.id):await getArt(a.key);await openArt(record);if(play)startPuzzle()}catch{notify('Connect to the internet to open artwork from another device.')}finally{b.disabled=puzzle.disabled=false}};b.onclick=()=>open(false);puzzle.onclick=()=>open(true);card.append(img,title,small,b,puzzle);$('galleryItems').append(card)}}catch{notify('Your gallery could not be opened on this device.')}}
