function stylePiece(b,i){b.style.backgroundImage=`url("${puzzleImage}")`;b.style.setProperty('--bgsize',`${grid.cols*100}% ${grid.rows*100}%`);b.style.setProperty('--pos',`${(i%grid.cols)*100/(grid.cols-1)}% ${Math.floor(i/grid.cols)*100/(grid.rows-1)}%`);b.style.setProperty('--ratio',grid.rows/grid.cols)}
function updateTimer(){$('timer').textContent=formatTime(clock.elapsed);$('pauseTimer').disabled=clock.complete||(!clock.running&&clock.elapsed===0);$('pauseTimer').textContent=paused?'Resume':'Pause'}
function createPuzzle(){if(!ready)return;puzzleImage=canvas.toDataURL('image/png');puzzleArtId=art.id;grid=puzzleGrid(Number($('difficulty').value));placed=new Set();selected=null;clock.reset();paused=false;puzzleReady=true;$('pauseOverlay').hidden=true;updateTimer();$('board').replaceChildren();$('tray').replaceChildren();$('board').style.gridTemplateColumns=`repeat(${grid.cols},1fr)`;$('board').style.gridTemplateRows=`repeat(${grid.rows},1fr)`;$('reference').src=puzzleImage;$('reference').hidden=true;$('hint').textContent='☀ Show picture';for(let i=0;i<grid.count;i++){const b=document.createElement('button');b.className='slot';b.textContent='·';b.setAttribute('aria-label',`Puzzle spot ${i+1}, row ${Math.floor(i/grid.cols)+1}, column ${i%grid.cols+1}`);b.onclick=()=>place(i,b);$('board').append(b)}for(const i of shuffled(Array.from({length:grid.count},(_,i)=>i))){const b=document.createElement('button');b.className='piece';b.dataset.piece=i;stylePiece(b,i);b.setAttribute('aria-label',`Select puzzle piece ${i+1}`);b.onclick=()=>{if(paused)return;clock.start();updateTimer();selected=i;document.querySelectorAll('.piece').forEach(p=>{p.classList.toggle('chosen',p===b);p.setAttribute('aria-pressed',String(p===b))});$('puzzleStatus').textContent='Now tap the spot where your piece belongs.'};$('tray').append(b)}$('puzzleStatus').textContent='Tap your first piece to start the timer.'}
function place(i,b){if(paused||selected===null||placed.has(i))return;if(selected!==i){notify('Try another spot. You’ve got this!');return}placed.add(i);stylePiece(b,i);b.className='slot placed';b.textContent='';b.disabled=true;document.querySelector(`[data-piece="${i}"]`).remove();selected=null;if(placed.size===grid.count){clock.finish();updateTimer();$('puzzleStatus').textContent=`Hooray! ${grid.count} pieces in ${formatTime(clock.elapsed)}. You made it and solved it!`;notify('✨ You made it, and you solved it! ✨')}else $('puzzleStatus').textContent=`${placed.size} of ${grid.count} pieces — keep going!`}
function pausePuzzle(){if(!puzzleReady||clock.complete)return;if(clock.running)clock.pause();if(clock.elapsed>0){paused=true;$('pauseOverlay').hidden=false;updateTimer()}}
function resumePuzzle(){if(!puzzleReady||clock.complete)return;paused=false;$('pauseOverlay').hidden=true;clock.start();updateTimer()}
async function startPuzzle(){if(!ready||!art){notify('Pick a page or open your artwork to make a puzzle.');view('library');return}try{await saveLocal();if(!puzzleReady||puzzleArtId!==art.id)createPuzzle();view('puzzle')}catch{}}
$('makePuzzle').onclick=startPuzzle;$('puzzleTab').onclick=startPuzzle;$('back').onclick=()=>view('studio');$('shuffle').onclick=createPuzzle;$('difficulty').onchange=createPuzzle;$('hint').onclick=()=>{$('reference').hidden=!$('reference').hidden;$('hint').textContent=$('reference').hidden?'☀ Show picture':'Hide picture'};$('pauseTimer').onclick=()=>paused?resumePuzzle():pausePuzzle();$('resume').onclick=resumePuzzle;setInterval(()=>{if(clock.running)updateTimer()},250);setInterval(()=>{if(profile&&navigator.onLine){flush();if(!$('gallery').hidden)gallery()}},30000);
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopDrawing();pausePuzzle();saveLocal().catch(()=>{})}else if(profile){flush();if(!$('gallery').hidden)gallery()}});window.addEventListener('pagehide',()=>{saveLocal().catch(()=>{});pausePuzzle()});
function openParent(){$('familyCodeArea').hidden=true;$('familyCode').value='';$('pairCode').value='';$('parentDialog').showModal()}
$('parentBtn').onclick=openParent;$('welcomeInstall').onclick=openParent;$('welcomePair').onclick=openParent;$('closeParent').onclick=()=>$('parentDialog').close();$('showCode').onclick=()=>{$('familyCode').value=family.match(/.{1,8}/g).join('-');$('familyCodeArea').hidden=false};$('copyCode').onclick=async()=>{try{await navigator.clipboard.writeText(family);notify('Family code copied. Keep it somewhere safe.')}catch{$('familyCode').select();notify('Select and copy the family code.')}};
$('pair').onclick=async()=>{const b=$('pair');b.disabled=true;$('pairStatus').textContent='Connecting…';try{await saveLocal();await flush();await pairFamily($('pairCode').value);art=null;ready=false;puzzleReady=false;profile='';$('welcome').hidden=false;$('app').hidden=true;$('switchBtn').hidden=true;$('parentDialog').close();notify('Connected! Pick a name to see your family’s artwork.')}catch(e){$('pairStatus').textContent=e.message==='Use the full 64-character family code.'?e.message:'Couldn’t connect. Check the family code and internet connection.'}finally{b.disabled=false}};
